<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { Button as FrappeButton } from 'frappe-ui'
import { Button } from '@/components/ui/button'
import { useSidebar } from '@/components/ui/sidebar'
import { useRoute, useRouter } from 'vue-router'
import { displayDialog } from '../composables/displayDialog'
import DialogPickup from '../components/DialogPickup.vue'

const { toggleSidebar, state, isMobile } = useSidebar()
const router = useRouter()
const route = useRoute()
const isNavVisible = ref(true)
let lastScrollY = 0

const openAddOrderDialog = async () => {
  if (route.path === '/order') {
    displayDialog.isDisplay = true
    return
  }

  displayDialog.isDisplay = false

  await router.push({
    path: '/order',
    query: {
      openAddOrder: '1',
    },
  })
}

function handleScroll() {
  const currentScrollY = window.scrollY

  if (currentScrollY <= 8) {
    isNavVisible.value = true
    lastScrollY = currentScrollY
    return
  }

  if (Math.abs(currentScrollY - lastScrollY) < 8) return

  isNavVisible.value = currentScrollY < lastScrollY
  lastScrollY = currentScrollY
}

onMounted(() => {
  lastScrollY = window.scrollY
  window.addEventListener('scroll', handleScroll, { passive: true })
})

onBeforeUnmount(() => {
  window.removeEventListener('scroll', handleScroll)
})

const navStyle = computed(() => {
  if (isMobile.value) {
    return { left: '0.5rem', right: '0.5rem' }
  }

  return {
    left:
      state.value === 'collapsed'
        ? 'calc(72px + 0.5rem)'
        : 'calc(16rem + 0.5rem)',
    right: '0.5rem',
  }
})
</script>
